package mini.lower

import mini.backend.*
import mini.frontend.sema.*

/*
 * Ir2Mir: `@WasmExport` (stdlib mini.wasm.WasmExport, WasmLib.kt in the backend). The annotated top-level functions of the program
 * become the exports of a wasm library; their signatures are checked here, whatever the target is, so that a mistake shows up
 * on the first build. The wrappers that convert the arguments are generated by the LLVM backend.
 */

internal const val WASM_EXPORT_FQ = "mini.wasm.WasmExport"
internal const val WASM_INIT_FACADES = "mini_wasm_init_facades"

private fun isJsIdentifier(n: String): Boolean {
    if (n.isEmpty()) return false
    for ((i, c) in n.withIndex()) {
        val ok = c.isLetter() || c == '_' || (i > 0 && c.isDigit())
        if (!ok) return false
    }
    return true
}

private fun Ir2Mir.wasmError(f: IrSimpleFunction, name: String, what: String): Nothing =
    throw UnsupportedConstruct("${location(f)}: error: @WasmExport function '$name': $what")

internal fun Ir2Mir.collectWasmExports(tops: List<Pair<IrFile, IrSimpleFunction>>): List<MirWasmExport> {
    val out = ArrayList<MirWasmExport>()
    val taken = HashMap<String, String>()
    for ((file, f) in tops) {
        if (file.isLib) continue
        val a = findAnnotation(f.annotations, WASM_EXPORT_FQ) ?: continue
        setFile(file)
        val given = a.arg
        val name = if (given != null && given.isNotEmpty()) given else f.name
        if (!isJsIdentifier(name)) wasmError(f, name, "the export name must be a JavaScript identifier (letters, digits and `_`; not starting with a digit)")
        if (WasmAbi.isReservedExportName(name)) wasmError(f, name, "the name is reserved for the module itself (`memory`, `load`, `MiniError`, names starting with `mini_` or `_`)")
        val prev = taken[name]
        if (prev != null) wasmError(f, name, "the export name is already used by `$prev`; give one of them another name: @WasmExport(\"other\")")
        taken[name] = f.name
        if (f.name == "main") wasmError(f, name, "`main` cannot be exported (a wasm library has no entry point)")
        if (f.typeParameters.isNotEmpty()) wasmError(f, name, "generic functions cannot be exported (their type parameters are erased); export a function with concrete types")
        if (f.isSuspend) wasmError(f, name, "suspend functions cannot be exported")
        for (p in f.parameters) {
            if (p.kind != IrParameterKind.Regular) wasmError(f, name, "extension functions cannot be exported; pass the receiver as a parameter")
            if (p.varargElementType != null) wasmError(f, name, "vararg parameter '${p.name}': pass an array instead")
        }
        for (p in f.parameters) {
            val t = mirType(p.type, p)
            if (WasmAbi.kindOf(t) == null || t === TUnit) wasmError(f, name, "parameter '${p.name}' has the type '${t.displayName}', which cannot cross the boundary. ${allowed()}")
        }
        val r = mirType(f.returnType, f)
        if (WasmAbi.kindOf(r) == null) wasmError(f, name, "the result type '${r.displayName}' cannot cross the boundary. ${allowed()}")
        out.add(MirWasmExport(name, functionNames[f]!!))
    }
    return out
}

private fun allowed(): String =
    "Allowed: Int, Long, Double, Float, Boolean, String, IntArray, LongArray, DoubleArray, FloatArray and non-null classes (as opaque handles); a result may also be Unit. Nullable types, Char, Byte, Short, Array<T>, collections of values and function types are not supported."

/** `mini_wasm_init_facades`: forces the top-level property initialisers of the program's files (what `main` does first in a program). */
internal fun Ir2Mir.wasmInitFunction(): MirFunction? {
    val force = facades.values.filter { !it.file.isLib }.map { MirStmt.Eval(MirExpr.ObjectGet(it.cName, it.type)) }
    if (force.isEmpty()) return null
    return MirFunction("mini.wasm.init", WASM_INIT_FACADES, emptyList(), TUnit, force)
}
